[data-n-ui][data-theme="dark"] {
  color-scheme: dark;
  --n-bg: #0a0a0a;
  --n-surface: #171717;
  --n-raised: #262626;
  --n-hover: #303030;
  --n-text: #fafafa;
  --n-muted: #a3a3a3;
  --n-border: #333333;
  --n-border-strong: #737373;
  --n-accent: #fafafa;
  --n-accent-hover: #e5e5e5;
  --n-accent-soft: #262626;
  --n-accent-ink: #fafafa;
  --n-on-accent: #0a0a0a;
  --n-success: #78d7ae;
  --n-success-soft: #193a2f;
  --n-warning: #f0c16b;
  --n-warning-soft: #3e3020;
  --n-danger: #ff9aa9;
  --n-danger-soft: #41252f;
  --n-shadow: 0 12px 40px #0005, 0 2px 8px #0003;
}
@media (prefers-color-scheme: dark) {
  [data-n-ui][data-theme="system"] {
    color-scheme: dark;
    --n-bg: #0a0a0a;
    --n-surface: #171717;
    --n-raised: #262626;
    --n-hover: #303030;
    --n-text: #fafafa;
    --n-muted: #a3a3a3;
    --n-border: #333333;
