  width: 14px;
  height: 14px;
}
.n-checkbox-indicator svg {
  display: block;
  width: 14px;
  height: 14px;
  overflow: visible;
}
.n-checkbox-indicator path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  opacity: 0;
  transition:
    stroke-dashoffset 200ms ease-in-out,
    opacity 200ms ease-in-out;
}
.n-checkbox[data-state="checked"] .n-checkbox-check {
  stroke-dashoffset: 0;
  opacity: 1;
  transition-delay: 200ms;
}
.n-checkbox[data-state="indeterminate"] .n-checkbox-minus {
  stroke-dashoffset: 0;
  opacity: 1;
}
.n-radio-group {
  display: grid;
  gap: 12px;
}
.n-radio-group-item {
  border-radius: 50%;
}
.n-radio-indicator {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--n-accent);
  opacity: 0;
  transform: scale(0);
  transition:
    transform 700ms var(--n-spring-radio),
    opacity 200ms ease;
}
.n-radio-indicator[data-state="checked"] {
  opacity: 1;
  transform: scale(1);
}
.n-choice {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 13px;
}
.n-slider {
  display: flex;
  align-items: center;
  position: relative;
  height: 24px;
  width: 100%;
  touch-action: none;
  user-select: none;
}
.n-slider-track {
  position: relative;
  flex: 1;
  height: 5px;
  background: var(--n-raised);
  border-radius: 99px;
}
.n-slider-range {
  position: absolute;
  height: 100%;
  background: var(--n-accent);
  border-radius: inherit;
}
.n-slider-thumb {
  display: block;
  width: 18px;
  height: 18px;
  background: var(--n-surface);
  border: 2px solid var(--n-accent);
  border-radius: 50%;
  box-shadow: 0 1px 3px #0002;
}
.n-slider[data-orientation="vertical"] {
  width: 24px;
  height: 160px;
  flex-direction: column;
}
.n-slider[data-orientation="vertical"] .n-slider-track {
  width: 5px;
}
.n-slider[data-orientation="vertical"] .n-slider-range {
  width: 100%;
  height: auto;
}
.n-toggle-group {
  display: inline-flex;
  gap: 4px;
}
.n-toggle,
.n-toggle-group-item {
  min-width: 36px;
  min-height: 36px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--n-muted);
  padding: 7px 12px;
  cursor: pointer;
}
.n-toggle:hover,
.n-toggle-group-item:hover {
  background: var(--n-raised);
}
.n-toggle[data-state="on"],
.n-toggle-group-item[data-state="on"] {
  background: var(--n-accent-soft);
  color: var(--n-accent-ink);
}
.n-avatar {
  display: inline-flex;
  vertical-align: middle;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  overflow: hidden;
  flex-shrink: 0;
  background: var(--n-accent-soft);
}
.n-avatar-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.n-avatar-fallback {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 600;
  color: var(--n-accent-ink);
}
.n-alert {
  border: 1px solid var(--n-border);
  border-radius: var(--n-radius);
  padding: 16px;
  background: var(--n-surface);
}
.n-alert-title {
  margin: 0 0 6px;
  font-size: 14px;
  font-weight: 600;
}
.n-separator {
  background: var(--n-border);
  height: 1px;
  width: 100%;
  flex-shrink: 0;
}
.n-separator[data-orientation="vertical"] {
  height: auto;
  align-self: stretch;
  width: 1px;
}
.n-breadcrumb-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  list-style: none;
  padding: 0;
  margin: 0;
  font-size: 13px;
}
.n-breadcrumb-item + .n-breadcrumb-item::before {
  content: "/";
  color: var(--n-muted);
  margin-inline-end: 10px;
}
.n-breadcrumb-link {
  color: var(--n-muted);
  text-decoration: none;
}
.n-breadcrumb-link:hover {
  color: var(--n-text);
}
.n-breadcrumb-page {
  color: var(--n-text);
}
.n-kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 21px;
  height: 22px;
  border: 1px solid var(--n-border);
  border-bottom-width: 2px;
  border-radius: 5px;
  background: var(--n-surface);
  padding: 2px 5px;
  font:
    11px ui-monospace,
    monospace;
  color: var(--n-muted);
}
.n-kbd-group {
  display: inline-flex;
  gap: 4px;
}
.n-marker {
  background: var(--n-accent-soft);
  color: var(--n-accent-ink);
  border-radius: 3px;
  padding: 1px 3px;
}
.n-heading {
  margin: 0 0 14px;
  font-size: 26px;
  line-height: 1.3;
  letter-spacing: -0.04em;
}
.n-text {
  font-size: 15px;
  line-height: 1.8;
  margin: 0 0 16px;
}
.n-code {
  background: var(--n-raised);
  border: 1px solid var(--n-border);
  border-radius: 4px;
  padding: 2px 5px;
  font:
    0.87em ui-monospace,
    monospace;
}
.n-blockquote {
  border-inline-start: 3px solid var(--n-accent);
  margin: 18px 0;
  padding: 4px 20px;
  font-size: 16px;
  color: var(--n-muted);
  line-height: 1.8;
}
.n-button-group {
  display: inline-flex;
  gap: 1px;
}
.n-button-group .n-button {
  border-radius: 0;
}
.n-button-group .n-button:first-child {
  border-start-start-radius: var(--n-radius);
  border-end-start-radius: var(--n-radius);
}
.n-button-group .n-button:last-child {
  border-start-end-radius: var(--n-radius);
  border-end-end-radius: var(--n-radius);
}
.n-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--n-border);
  border-radius: 12px;
}
.n-item-content {
  flex: 1;
  min-width: 0;
}
.n-item-title {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 4px;
}
.n-item-actions,
.n-item-media {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.n-item-group {
  display: grid;
  gap: 10px;
}
.n-aspect-ratio {
  overflow: hidden;
  width: 100%;
}
.n-aspect-ratio img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.n-table-scroll {
  width: 100%;
  overflow-x: auto;
}
.n-table {
  border-collapse: collapse;
  width: 100%;
  text-align: start;
  font-size: 13px;
}
.n-table-head {
  padding: 12px 14px;
  text-align: start;
  font-weight: 550;
  color: var(--n-muted);
  background: var(--n-raised);
  white-space: nowrap;
}
.n-table-cell {
  padding: 14px;
  border-bottom: 1px solid var(--n-border);
}
.n-table-row[data-selected="true"] {
  background: var(--n-accent-soft);
}
.n-table-caption {
  padding: 14px;
  font-size: 12px;
  color: var(--n-muted);
  caption-side: bottom;
}
.n-table-toolbar {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-bottom: 16px;
}
.n-table-toolbar .n-input {
  max-width: 260px;
}
.n-column-picker {
  position: relative;
  margin-inline-start: auto;
  font-size: 12px;
  flex-shrink: 0;
}
.n-column-picker summary {
  cursor: pointer;
  padding: 9px;
  border: 1px solid var(--n-border);
  border-radius: 7px;
}
.n-column-picker[open] {
  padding: 8px;
  background: var(--n-surface);
  border: 1px solid var(--n-border);
  border-radius: 10px;
}
.n-column-picker label {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px;
}
.n-sort-button {
  display: flex;
  gap: 8px;
  border: 0;
  padding: 0;
  font: inherit;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.n-table-footer-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding-top: 16px;
  font-size: 12px;
  color: var(--n-muted);
  flex-wrap: wrap;
}
.n-pagination {
  display: flex;
  align-items: center;
  gap: 20px;
  justify-content: center;
  font-size: 13px;
}
.n-sheet {
  position: fixed;
  z-index: 101;
  background: var(--n-surface);
  padding: 28px;
  box-shadow: var(--n-shadow);
  overflow-y: auto;
  animation: n-panel-in var(--n-duration-slow) var(--n-ease);
}
.n-sheet[data-side="right"] {
  inset: 0 0 0 auto;
  width: min(400px, 90vw);
}
.n-sheet[data-side="left"] {
  inset: 0 auto 0 0;
  width: min(400px, 90vw);
}
.n-sheet[data-side="top"] {
  inset: 0 0 auto;
  max-height: 85dvh;
}
.n-sheet[data-side="bottom"] {
  inset: auto 0 0;
  max-height: 85dvh;
}
.n-sheet[data-state="closed"] {
  animation: n-fade-out var(--n-duration-fast) var(--n-ease-exit);
}
.n-drawer {
  position: fixed;
  z-index: 101;
  background: var(--n-surface);
  padding: 20px 28px 32px;
  border-radius: 24px 24px 0 0;
  overflow-y: auto;
  max-height: 90dvh;
}
.n-drawer[data-vaul-drawer-direction="bottom"] {
  bottom: 0;
  left: 0;
  right: 0;
}
.n-drawer[data-vaul-drawer-direction="top"] {
  top: 0;
  left: 0;
  right: 0;
  border-radius: 0 0 24px 24px;
}
.n-drawer[data-vaul-drawer-direction="left"] {
  left: 0;
  top: 0;
  bottom: 0;
  width: min(400px, 90vw);
  max-height: 100dvh;
  border-radius: 0 24px 24px 0;
}
.n-drawer[data-vaul-drawer-direction="right"] {
  right: 0;
  top: 0;
  bottom: 0;
  width: min(400px, 90vw);
  max-height: 100dvh;
  border-radius: 24px 0 0 24px;
}
.n-drawer-handle {
  width: 44px;
  height: 5px;
  background: var(--n-border-strong);
  border-radius: 20px;
  margin: 0 auto 24px;
}
.n-command {
  width: 100%;
  border: 1px solid var(--n-border);
  border-radius: 12px;
  overflow: hidden;
  background: var(--n-surface);
}
.n-command-input {
  width: 100%;
  border: 0;
  border-bottom: 1px solid var(--n-border);
  color: var(--n-text);
  background: transparent;
  padding: 16px;
  font-size: 14px;
}
.n-command-input:focus-visible {
  outline: none;
  outline-offset: 0;
  border-bottom-color: var(--n-border-strong);
}
.n-command-list {
  max-height: 290px;
  overflow-y: auto;
  padding: 6px;
}
.n-command-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 7px;
  font-size: 13px;
  cursor: pointer;
}
.n-command-item[data-selected="true"] {
  background: var(--n-accent-soft);
  color: var(--n-accent-ink);
}
.n-command-empty {
  padding: 24px;
  text-align: center;
  font-size: 13px;
  color: var(--n-muted);
}
.n-command-group [cmdk-group-heading] {
  padding: 10px 12px 6px;
  font-size: 11px;
  font-weight: 600;
  color: var(--n-muted);
}
.n-combobox-trigger {
  width: 264px;
  max-width: 100%;
  justify-content: space-between;
}
.n-combobox-trigger > .n-button-label {
  width: 100%;
  justify-content: space-between;
}
.n-combobox-popover {
  padding: 0;
  width: max(
    var(--radix-popover-trigger-width),
    var(--n-combobox-min-width, 240px)
  );
  max-width: var(--radix-popover-content-available-width);
}
.n-combobox-popover .n-command {
  border: 0;
}
.n-combobox-popover .n-command-input {
  height: 36px;
  padding: 0 12px;
  font-size: 13px;
  background: var(--n-surface);
}
.n-calendar {
  --rdp-accent-color: var(--n-accent);
  --rdp-accent-background-color: var(--n-accent-soft);
  --rdp-day-height: 36px;
  --rdp-day-width: 36px;
  --rdp-day_button-height: 34px;
  --rdp-day_button-width: 34px;
  font-size: 13px;
}
.n-calendar .rdp-caption_label {
  font-size: 14px;
}
.n-calendar .rdp-day_button {
  border-radius: 8px;
  font-size: 13px;
}
.n-calendar .rdp-selected {
  font-size: inherit;
  font-weight: 600;
}
.n-calendar .rdp-selected .rdp-day_button {
  background: var(--n-accent);
  color: var(--n-on-accent);
}
.n-calendar .rdp-range_middle .rdp-day_button {
  background: var(--n-accent-soft);
  color: var(--n-accent-ink);
}
.n-calendar-popover {
  width: auto;
  padding: 16px;
}
.n-otp {
  display: flex;
  gap: 8px;
  align-items: center;
}
.n-otp-slot {
  display: grid;
  place-items: center;
  position: relative;
  width: 42px;
  height: 48px;
  border: 1px solid var(--n-border);
  border-radius: 9px;
  background: var(--n-surface);
  font-size: 20px;
}
.n-otp-slot[data-active="true"] {
  outline: none;
  border-color: var(--n-border-strong);
  box-shadow: var(--n-focus);
}
.n-otp-caret {
  position: absolute;
  width: 1px;
  height: 22px;
  background: var(--n-text);
  animation: n-blink 1s step-end infinite;
}
.n-resizable {
  border: 1px solid var(--n-border);
  border-radius: 12px;
  overflow: hidden;
  min-height: 180px;
}
.n-resizable-handle {
  background: var(--n-border);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 5px;
  color: var(--n-muted);
  position: relative;
}
.n-resizable-handle span {
  background: var(--n-raised);
  border: 1px solid var(--n-border);
  border-radius: 4px;
  font-size: 12px;
  padding: 3px 0;
  z-index: 1;
}
.n-resizable[data-group-orientation="vertical"] .n-resizable-handle {
  width: 100%;
  height: 5px;
}
.n-chart {
  height: 240px;
  min-width: 0;
  width: 100%;
  font-size: 11px;
}
.n-chart .recharts-cartesian-axis-tick text {
  fill: var(--n-muted);
}
.n-chart .recharts-cartesian-grid line {
  stroke: var(--n-border);
}
.n-chart .recharts-default-tooltip {
  background: var(--n-surface) !important;
  border-color: var(--n-border) !important;
  border-radius: 8px;
}
.n-toast {
  background: var(--n-surface) !important;
  color: var(--n-text) !important;
  border-color: var(--n-border) !important;
  font-family: inherit !important;
  box-shadow: var(--n-shadow) !important;
}
.n-toast-description {
  color: var(--n-muted) !important;
}
.n-carousel-viewport {
  overflow: hidden;
  border-radius: 12px;
}
.n-carousel-track {
  display: flex;
  touch-action: pan-y pinch-zoom;
}
.n-carousel-slide {
  flex: 0 0 100%;
  min-width: 0;
}
.n-carousel-controls {
  display: flex;
  justify-content: center;
  gap: 20px;
  align-items: center;
  margin-top: 16px;
  font-size: 12px;
  color: var(--n-muted);
}
.n-scroll-area {
  overflow: hidden;
  position: relative;
}
.n-scroll-area-viewport {
  width: 100%;
  height: 100%;
  border-radius: inherit;
}
.n-scroll-area-scrollbar {
  display: flex;
  padding: 2px;
  user-select: none;
  touch-action: none;
  width: 8px;
}
.n-scroll-area-scrollbar[data-orientation="horizontal"] {
  flex-direction: column;
  height: 8px;
  width: auto;
}
.n-scroll-area-thumb {
  flex: 1;
  background: var(--n-border-strong);
  border-radius: 10px;
}
.n-collapsible-content {
  overflow: hidden;
}
.n-collapsible-content[data-state="open"] {
  animation: n-collapse-open var(--n-duration-normal) var(--n-ease);
}
.n-collapsible-content[data-state="closed"] {
  animation: n-collapse-close var(--n-duration-fast) var(--n-ease-exit);
}
.n-navigation-menu {
  position: relative;
  z-index: 10;
}
.n-navigation-menu-list {
  display: flex;
  list-style: none;
  gap: 6px;
  padding: 0;
  margin: 0;
}
.n-navigation-menu-trigger,
.n-navigation-menu-link {
  display: block;
  padding: 10px 14px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--n-text);
  text-decoration: none;
  font-size: 13px;
}
.n-navigation-menu-trigger:hover,
.n-navigation-menu-link:hover {
  background: var(--n-raised);
}
.n-navigation-menu-content {
  position: absolute;
  top: 100%;
  left: 0;
  min-width: 230px;
  background: var(--n-surface);
  padding: 10px;
  border: 1px solid var(--n-border);
  border-radius: 12px;
  box-shadow: var(--n-shadow);
  animation: n-panel-in var(--n-duration-normal) var(--n-ease);
}
.n-navigation-menu-viewport {
  position: relative;
  width: var(--radix-navigation-menu-viewport-width);
  height: var(--radix-navigation-menu-viewport-height);
  transition:
    width var(--n-duration-normal),
    height var(--n-duration-normal);
}
.n-dropzone {
  border: 1px dashed var(--n-border-strong);
  border-radius: 14px;
  background: var(--n-surface);
  display: grid;
  justify-items: center;
  gap: 12px;
  padding: 26px;
  text-align: center;
  font-size: 14px;
  transition:
    background var(--n-duration-fast),
    border-color var(--n-duration-fast);
}
.n-dropzone[data-dragging="true"] {
  background: var(--n-accent-soft);
  border-color: var(--n-accent);
}
.n-upload-symbol {
  font-size: 25px;
  color: var(--n-accent);
  background: var(--n-accent-soft);
  border-radius: 12px;
  padding: 7px 15px;
}
.n-upload-list {
  list-style: none;
  padding: 0;
  margin: 10px 0 0;
}
.n-upload-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  font-size: 13px;
}
.n-upload-list small {
  display: block;
  color: var(--n-muted);
  font-size: 11px;
  margin-top: 3px;
}
.n-tree {
  font-size: 13px;
}
.n-tree [role="treeitem"] {
  padding: 10px 12px;
  padding-inline-start: calc((var(--tree-level) - 1) * 20px + 12px);
  border-radius: 8px;
  cursor: pointer;
  display: flex;
  gap: 10px;
  align-items: center;
}
.n-tree [role="treeitem"]:hover {
  background: var(--n-raised);
}
.n-tree [aria-selected="true"] {
  background: var(--n-accent-soft);
  color: var(--n-accent-ink);
}
.n-tree [aria-disabled="true"] {
  pointer-events: none;
}
.n-sortable {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 8px;
}
.n-sortable-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px;
  background: var(--n-surface);
  border: 1px solid var(--n-border);
  border-radius: 9px;
  font-size: 13px;
  position: relative;
}
.n-sortable-row[data-dragging="true"] {
  box-shadow: var(--n-shadow);
  z-index: 2;
}
.n-drag-handle {
  touch-action: none;
  cursor: grab;
  border: 0;
  background: transparent;
  color: var(--n-muted);
  padding: 5px 7px;
  font-size: 20px;
}
.n-sidebar-layout {
  display: flex;
  min-height: 300px;
  overflow: hidden;
  border: 1px solid var(--n-border);
  border-radius: 12px;
}
.n-sidebar {
  width: 220px;
  flex-shrink: 0;
  overflow: hidden;
  border-inline-end: 1px solid var(--n-border);
  background: var(--n-surface);
  transition: width var(--n-duration-normal) var(--n-ease);
}
.n-sidebar[data-open="false"] {
  width: 0;
  border: 0;
}
.n-sidebar-content {
  padding: 16px;
  width: 220px;
}
.n-sidebar-group {
  margin-top: 20px;
}
.n-sidebar-group-label {
  color: var(--n-muted);
  font-size: 10px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  margin: 0 0 10px 8px;
}
.n-sidebar-menu-button {
  display: flex;
  width: 100%;
  border: 0;
  border-radius: 8px;
  padding: 9px;
  background: transparent;
  color: var(--n-text);
  text-align: start;
  font-size: 13px;
  cursor: pointer;
}
.n-sidebar-menu-button:hover {
  background: var(--n-raised);
}
.n-sidebar-inset {
  flex: 1;
  min-width: 0;
  padding: 16px;
}
.n-attachment {
  display: inline-flex;
  gap: 12px;
  align-items: center;
  padding: 12px 16px;
  color: var(--n-text);
  text-decoration: none;
  border: 1px solid var(--n-border);
  background: var(--n-surface);
  border-radius: 10px;
  font-size: 13px;
}
.n-attachment small {
  display: block;
  color: var(--n-muted);
  font-size: 11px;
  margin-top: 4px;
}
.n-message {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  margin: 20px 0;
  font-size: 14px;
  line-height: 1.7;
}
.n-message[data-from="user"] {
  align-items: flex-end;
}
.n-message-content {
  max-width: 90%;
}
.n-message-actions {
  display: flex;
  gap: 4px;
}
.n-bubble {
  padding: 12px 16px;
  border-radius: 14px 14px 14px 3px;
  background: var(--n-raised);
  font-size: 14px;
  line-height: 1.7;
}
.n-bubble[data-from="user"] {
  background: var(--n-accent-soft);
  color: var(--n-accent-ink);
  border-radius: 14px 14px 3px 14px;
}
.n-message-scroller-shell {
  position: relative;
}
.n-message-scroller {
  height: 280px;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 16px;
}
.n-scroll-bottom {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
  box-shadow: var(--n-shadow);
}
.n-questionnaire {
  display: grid;
  gap: 20px;
}
.n-fieldset {
  border: 1px solid var(--n-border);
  border-radius: 10px;
  padding: 14px;
  display: grid;
  gap: 12px;
}
.n-fieldset legend {
  font-size: 13px;
  font-weight: 600;
  padding: 0 6px;
}
.n-nav-link {
  color: var(--n-muted);
  text-decoration: none;
  border-radius: 7px;
  transition:
    background var(--n-duration-fast),
    color var(--n-duration-fast);
}
.n-nav-link:hover {
  color: var(--n-text);
}
.n-nav-link[data-active="true"] {
  color: var(--n-accent-ink);
  background: var(--n-accent-soft);
}
@keyframes n-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes n-shimmer {
  to {
    background-position: -200% 0;
  }
}
@keyframes n-blink {
  50% {
    opacity: 0;
  }
}
@keyframes n-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes n-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes n-dialog-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
@keyframes n-dialog-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.98);
  }
}
@keyframes n-panel-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
@keyframes n-accordion-open {
  from {
    height: 0;
  }
  to {
    height: var(--radix-accordion-content-height);
  }
}
@keyframes n-accordion-close {
  from {
    height: var(--radix-accordion-content-height);
  }
  to {
    height: 0;
  }
}
@keyframes n-collapse-open {
  from {
    height: 0;
  }
  to {
    height: var(--radix-collapsible-content-height);
  }
}
@keyframes n-collapse-close {
  from {
    height: var(--radix-collapsible-content-height);
  }
  to {
    height: 0;
  }
}

/* Reference motion profiles: spring popups, 200ms menus, 500ms blurred tabs. */
.n-popover,
.n-hover-card-content,
.n-tooltip {
  transform-origin: var(--radix-popper-transform-origin, center);
  animation: n-popup-in var(--n-duration-panel) var(--n-spring-panel);
}
.n-popover[data-state="closed"],
.n-hover-card-content[data-state="closed"],
.n-tooltip[data-state="closed"] {
  animation: n-popup-out var(--n-duration-panel) var(--n-spring-panel);
  pointer-events: none;
}
.n-tooltip-arrow {
  fill: var(--n-text);
}
.n-dropdown-menu-content,
.n-dropdown-menu-sub-content {
  animation: n-menu-in 200ms ease-in-out;
}
.n-dropdown-menu-content[data-state="closed"],
.n-dropdown-menu-sub-content[data-state="closed"] {
  animation: n-menu-out 200ms ease-in-out;
  pointer-events: none;
}
.n-tabs-list {
  padding: 3px;
  gap: 0;
  border-radius: 8px;
}
.n-tabs-trigger {
  padding: 5px 10px;
}
.n-tabs-indicator {
  border-radius: 6px;
  transition:
    transform var(--n-duration-layout) var(--n-spring-layout),
    width var(--n-duration-layout) var(--n-spring-layout),
    height var(--n-duration-layout) var(--n-spring-layout);
}
.n-tabs-content {
  margin-top: 8px;
  animation: n-tab-in 500ms ease-in-out;
}
.n-sidebar {
  transition-duration: 500ms;
}
@keyframes n-popup-in {
  from {
    opacity: 0;
    transform: scale(0.5);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes n-popup-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.5);
  }
}
@keyframes n-menu-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes n-menu-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.95);
  }
}
@keyframes n-tab-in {
  from {
    opacity: 0;
    filter: blur(4px);
  }
  to {
    opacity: 1;
    filter: blur(0);
  }
}

[data-n-highlight-root] {
  position: relative;
  isolation: isolate;
}
.n-moving-highlight {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
  z-index: -1;
  border-radius: 5px;
  background: var(--n-raised);
  opacity: 0;
  transition:
    transform 450ms cubic-bezier(0.22, 1, 0.36, 1),
    width 450ms var(--n-ease),
    height 450ms var(--n-ease),
    opacity 150ms;
}
.n-moving-highlight[data-variant="line"] {
  background: transparent;
  border-inline-start: 2px solid var(--n-border-strong);
  border-radius: 0;
}
[data-n-highlight-root] > .n-moving-highlight ~ [data-highlighted],
.n-tree[data-n-highlight-root] [role="treeitem"]:hover,
.n-sidebar-content[data-n-highlight-root] .n-sidebar-menu-button:hover {
  background: transparent;
}
.n-tree [role="treeitem"] {
  position: relative;
  padding-block: 7px;
}
.n-animated-size {
  transition: height 500ms ease-in-out;
  overflow: hidden;
}
.n-animated-size-inner {
  display: flow-root;
}
.n-code-block {
  border: 1px solid var(--n-border);
  border-radius: 10px;
  background: var(--n-bg);
  min-width: 0;
  overflow: hidden;
}
.n-code-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 36px;
  padding: 6px 12px;
  background: var(--n-raised);
  color: var(--n-muted);
  font-size: 12px;
  border-bottom: 1px solid var(--n-border);
}
.n-code-header button {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  background: transparent;
  border: 0;
  border-radius: 5px;
  color: var(--n-muted);
  cursor: pointer;
}
.n-code-header button:hover {
  color: var(--n-text);
  background: var(--n-hover);
}
.n-code-header svg {
  width: 14px;
  height: 14px;
}
.n-code-block pre {
  margin: 0;
  padding: 16px;
  overflow: auto;
  min-height: 120px;
  font-size: 12px;
  line-height: 1.8;
  tab-size: 2;
}
.n-code-block code {
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
}
.n-code-tabs {
  border: 1px solid var(--n-border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--n-bg);
}
.n-code-tabs > .n-tabs-list {
  display: flex;
  justify-content: start;
  border-radius: 0;
  border-bottom: 1px solid var(--n-border);
}
.n-code-tabs .n-tabs-indicator {
  background: transparent;
  box-shadow: none;
  border-radius: 0;
  border-bottom: 1px solid var(--n-accent);
}
.n-code-tabs .n-tabs-content {
  margin: 0;
}
.n-code-tabs .n-code-block {
  border: 0;
  border-radius: 0;
}
.n-code-tabs .n-code-header {
  background: transparent;
}
.n-notifications {
  width: min(340px, 100%);
  padding: 12px;
  border-radius: 24px;
  background: var(--n-hover);
  box-shadow: 0 2px 4px #0000000a;
}
.n-notification-stack {
  position: relative;
  height: 82px;
  transition: height 600ms var(--n-spring-panel);
}
.n-notifications[data-expanded="true"] .n-notification-stack {
  height: calc(var(--notification-count) * 64px);
}
.n-notification-card {
  position: absolute;
  inset: 0 0 auto;
  height: 60px;
  padding: 10px 14px;
  border: 1px solid var(--n-border);
  border-radius: 16px;
  background: var(--n-raised);
  box-shadow: 0 2px 3px #00000012;
  transform-origin: center top;
  transform: translateY(calc(var(--notification-index) * 8px))
    scale(calc(1 - var(--notification-index) * 0.04));
  transition:
    transform 600ms var(--n-spring-panel),
    opacity 200ms;
}
.n-notifications[data-expanded="true"] .n-notification-card {
  transform: translateY(calc(var(--notification-index) * 64px));
}
.n-notification-card strong {
  display: block;
  font-size: 13px;
  font-weight: 550;
  padding-inline-end: 30px;
}
.n-notification-card p {
  margin: 3px 0 0;
  font-size: 11px;
  color: var(--n-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.n-notification-card time {
  position: absolute;
  right: 12px;
  top: 12px;
  font-size: 10px;
  color: var(--n-muted);
}
.n-notification-toggle {
  display: flex;
  gap: 8px;
  align-items: center;
  border: 0;
  background: transparent;
  color: var(--n-text);
  font-size: 12px;
  padding: 8px 2px 0;
  cursor: pointer;
}
.n-notification-toggle span {
  display: grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--n-muted);
  color: var(--n-surface);
}
.n-pinned-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 340px;
  width: 100%;
  padding-block: 8px;
}
.n-pin-row {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 14px;
  padding: 7px 8px;
  background: var(--n-hover);
  min-height: 48px;
}
.n-pin-row:has(.n-pin-group-label) {
  margin-top: 44px;
}
.n-pin-group-label {
  position: absolute;
  top: -34px;
  left: 8px;
  margin: 0;
  font-size: 12px;
  color: var(--n-muted);
}
.n-pin-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: var(--n-surface);
  flex-shrink: 0;
}
.n-pin-icon svg {
  width: 18px;
  height: 18px;
}
.n-pin-copy {
  flex: 1;
  min-width: 0;
}
.n-pin-copy strong {
  display: block;
  font-size: 12px;
  font-weight: 550;
}
.n-pin-copy small {
  display: block;
  color: var(--n-muted);
  font-size: 10px;
}
.n-pin-row button {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 6px;
  border-radius: 50%;
  border: 0;
  background: var(--n-border);
  color: var(--n-muted);
  cursor: pointer;
  transition:
    background 200ms,
    transform 200ms var(--n-ease);
}
.n-pin-row button[aria-pressed="true"] {
  background: var(--n-accent);
  color: var(--n-on-accent);
}
.n-pin-row button:hover {
  transform: scale(1.08);
}
.n-pin-row button:active {
  transform: scale(0.95);
}
.n-pin-row button svg {
  width: 16px;
  height: 16px;
}
.n-todo-list {
  padding: 6px 18px;
  background: var(--n-raised);
  border-radius: 16px;
  max-width: 360px;
}
.n-todo-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-block: 20px;
  font-size: 13px;
  cursor: pointer;
}
.n-todo-row + .n-todo-row {
  border-top: 1px solid var(--n-border);
}
.n-todo-row > span {
  position: relative;
}
.n-todo-row > span > svg {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  fill: none;
  stroke: currentColor;
  stroke-width: 1;
  pointer-events: none;
}
.n-todo-row > span > svg path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset 1000ms ease-in-out;
}
.n-todo-row[data-complete="true"] > span > svg path {
  stroke-dashoffset: 0;
}
.n-shine-card {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding: 22px;
  border-radius: 12px;
  background: #050505;
  color: #fafafa;
  max-width: 400px;
}
.n-shine-card::after {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -100%;
  background: linear-gradient(
    110deg,
    transparent 40%,
    #ffffff12 47%,
    #ffffff20 50%,
    #ffffff12 53%,
    transparent 60%
  );
  animation: n-shine var(--shine-duration, 3000ms) linear infinite;
}
.n-shine-card h3 {
  font-size: 20px;
  margin: 0 0 8px;
}
.n-shine-card p {
  font-size: 14px;
  line-height: 1.6;
  margin: 0;
}
@keyframes n-shine {
  from {
    transform: translateX(-55%);
  }
  to {
    transform: translateX(55%);
  }
}
.n-relative-time {
  display: grid;
  gap: 7px;
  border: 1px solid var(--n-border);
  padding: 16px;
  border-radius: 9px;
  background: var(--n-surface);
  max-width: 100%;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.n-time-row {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}
.n-time-row abbr {
  background: var(--n-raised);
  text-decoration: none;
  padding: 1px 4px;
}
.n-time-row time {
  color: var(--n-muted);
}
.n-preview-link {
  color: var(--n-text);
  text-underline-offset: 3px;
}
.n-preview-link-card {
  padding: 10px;
  width: 280px;
}
.n-preview-link-card img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 5px;
}
.n-radial-trigger {
  display: grid;
  place-items: center;
  min-height: 280px;
  width: 100%;
  border: 1px dashed var(--n-border);
  border-radius: 12px;
  color: var(--n-muted);
  font-size: 13px;
  text-align: center;
  padding: 20px;
}
.n-radial-menu {
  position: relative;
  width: 224px;
  height: 224px;
  min-width: 224px;
  padding: 0;
  border: 8px solid var(--n-surface);
  border-radius: 50%;
  overflow: hidden;
  background: var(--n-raised);
  box-shadow: 0 8px 24px #0002;
  animation: n-popup-in 600ms var(--n-spring-panel);
}
.n-radial-menu .n-radial-item {
  position: absolute;
  inset: 0;
  display: block;
  padding: 0;
  border: 0;
  border-radius: 0;
  width: 100%;
  height: 100%;
  background: var(--n-raised);
  color: var(--n-muted);
  cursor: pointer;
}
.n-radial-menu .n-radial-item[data-highlighted],
.n-radial-menu .n-radial-item:focus-visible {
  background: var(--n-border);
  color: var(--n-text);
  outline: none;
}
.n-radial-item span {
  position: absolute;
  left: var(--radial-x);
  top: var(--radial-y);
  transform: translate(-50%, -50%);
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
}
.n-radial-item svg {
  width: 18px;
  height: 18px;
}
.n-radial-center {
  position: absolute;
  inset: 34%;
  border: 4px solid var(--n-surface);
  border-radius: 50%;
  background: var(--n-raised);
  pointer-events: none;
}
.n-step-dialog {
  padding: 0;
  border-radius: 12px;
  width: min(380px, calc(100vw - 32px));
  overflow: hidden;
}
.n-step-dialog .n-dialog-close {
  top: 8px;
  right: 8px;
}
.n-step-body {
  padding: 24px 20px;
  animation: n-step-forward 450ms ease-in-out;
}
.n-step-body[data-direction="back"] {
  animation-name: n-step-back;
}
.n-step-body .n-dialog-title {
  font-size: 16px;
}
.n-step-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-top: 1px solid var(--n-border);
  background: var(--n-bg);
}
.n-step-footer .n-button {
  border-radius: 999px;
  min-height: 28px;
}
@keyframes n-step-forward {
  from {
    opacity: 0;
    transform: translateX(35%);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}
@keyframes n-step-back {
  from {
    opacity: 0;
    transform: translateX(-35%);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}
.n-spinner-bars {
  position: relative;
  display: inline-block;
  width: 22px;
  height: 22px;
}
.n-spinner-bars i {
  position: absolute;
  left: 10px;
  top: 1px;
  width: 2px;
  height: 6px;
  border-radius: 2px;
  background: currentColor;
  transform-origin: 1px 10px;
  transform: rotate(calc(var(--spinner-index) * 30deg));
  animation: n-spinner-bars 1200ms linear infinite;
  animation-delay: calc(var(--spinner-index) * -100ms);
}
@keyframes n-spinner-bars {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0.15;
  }
}
.n-otp {
  gap: 5px;
}
.n-otp-slot {
  border-radius: 8px;
  width: 36px;
  height: 40px;
  background: var(--n-surface);
  transition:
    border-color 200ms,
    box-shadow 200ms;
}
.n-otp-slot[data-active="true"] {
  border-color: var(--n-border-strong);
  box-shadow: 0 0 0 2px
    color-mix(in srgb, var(--n-border-strong) 25%, transparent);
}
.n-otp-separator {
  color: var(--n-muted);
  margin-inline: 2px;
}
.n-sidebar[data-collapsible="icon"][data-open="false"] {
  width: 56px;
  border-inline-end: 1px solid var(--n-border);
}
.n-sidebar[data-collapsible="icon"] .n-sidebar-content {
  width: 100%;
  padding: 12px 8px;
}
.n-sidebar-menu-button {
  align-items: center;
  gap: 10px;
  overflow: hidden;
}
.n-sidebar-menu-icon {
  display: grid;
  place-items: center;
  width: 16px;
  flex: 0 0 16px;
}
.n-sidebar-menu-label {
  white-space: nowrap;
  transition: opacity 200ms;
}
.n-sidebar[data-collapsible="icon"][data-open="false"] .n-sidebar-menu-label {
  opacity: 0;
  width: 0;
}
.n-sidebar[data-collapsible="icon"][data-open="false"] .n-sidebar-group-label,
.n-sidebar[data-collapsible="icon"][data-open="false"]
  .n-sidebar-content
  > strong {
  visibility: hidden;
  white-space: nowrap;
}
.n-sidebar-menu-button[aria-pressed="true"] {
  background: var(--n-accent-soft);
  color: var(--n-accent-ink);
}
.n-relative-time {
  width: max-content;
}
.n-code-string {
  color: #296479;
}
.n-code-keyword {
  color: #815282;
}
.n-code-number {
  color: #86591d;
}
.n-code-comment {
  color: var(--n-muted);
}
[data-n-ui][data-theme="dark"] .n-code-string {
  color: #9ccfd8;
}
[data-n-ui][data-theme="dark"] .n-code-keyword {
  color: #d3b2e8;
}
[data-n-ui][data-theme="dark"] .n-code-number {
  color: #e0b781;
}
@media (prefers-color-scheme: dark) {
  [data-n-ui][data-theme="system"] .n-code-string {
    color: #9ccfd8;
  }
  [data-n-ui][data-theme="system"] .n-code-keyword {
    color: #d3b2e8;
  }
  [data-n-ui][data-theme="system"] .n-code-number {
    color: #e0b781;
  }
}
.n-notifications:not([data-expanded="true"])
  .n-notification-card:nth-child(n + 4) {
  opacity: 0;
}
.n-notifications:not([data-expanded="true"]) .n-notification-card {
  transform: translateY(calc(min(var(--notification-index), 2) * 8px))
    scale(calc(1 - min(var(--notification-index), 2) * 0.04));
}
.n-navigation-menu-content {
  border-radius: 8px;
  transform-origin: top center;
  animation: n-menu-in 200ms ease-in-out;
}
.n-navigation-menu-content[data-motion="from-start"] {
  animation: n-nav-from-start 250ms ease;
}
.n-navigation-menu-content[data-motion="from-end"] {
  animation: n-nav-from-end 250ms ease;
}
.n-navigation-menu-content[data-motion="to-start"] {
  animation: n-nav-to-start 200ms ease;
}
.n-navigation-menu-content[data-motion="to-end"] {
  animation: n-nav-to-end 200ms ease;
}
@keyframes n-nav-from-start {
  from {
    opacity: 0;
    transform: translateX(-30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
@keyframes n-nav-from-end {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
@keyframes n-nav-to-start {
  to {
    opacity: 0;
    transform: translateX(-30px);
  }
}
@keyframes n-nav-to-end {
  to {
    opacity: 0;
    transform: translateX(30px);
  }
}
.n-step-overlay {
  background: #000c;
  backdrop-filter: none;
}
.n-radial-menu {
  z-index: 110;
  background: var(--n-border);
  color: var(--n-text);
  outline: none;
}
.n-radial-menu[data-state="closed"] {
  animation: n-popup-out 600ms var(--n-spring-panel);
  pointer-events: none;
}
/* User preferences always win over theme presets and third-party animations. */
[data-n-ui][data-motion="reduced"],
[data-n-ui][data-motion="reduced"] *,
[data-n-ui][data-motion="reduced"] *::before,
[data-n-ui][data-motion="reduced"] *::after {
  animation-duration: 0.01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.01ms !important;
  transition-delay: 0ms !important;
  scroll-behavior: auto !important;
}
@media (prefers-reduced-motion: reduce) {
  [data-n-ui],
  [data-n-ui] *,
  [data-n-ui] *::before,
  [data-n-ui] *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    transition-delay: 0ms !important;
    scroll-behavior: auto !important;
  }
}
@media (forced-colors: active) {
  .n-command-input:focus-visible {
    outline: 1px solid Highlight;
    outline-offset: -2px;
  }
  .n-button,
  .n-switch,
  .n-checkbox,
  .n-radio-group-item,
  .n-tabs-indicator,
  .n-slider-thumb {
    border: 1px solid ButtonText;
  }
  .n-switch-thumb,
  .n-radio-indicator {
    background: Highlight;
  }
}

/* A single moving surface owns both active and hover presentation. */
.n-sidebar-content[data-n-highlight-root]
  .n-sidebar-menu-button:is(:hover, [aria-pressed="true"]),
.n-tree[data-n-highlight-root]
  [role="treeitem"]:is(:hover, [aria-selected="true"]) {
  background: transparent;
}
.n-icon {
  display: inline-block;
  flex-shrink: 0;
  vertical-align: middle;
}
.n-select-trigger > span:last-child,
.n-select-item > span:last-child {
  display: inline-flex;
  align-items: center;
}
.n-column-picker summary {
  display: flex;
  align-items: center;
  gap: 6px;
  list-style: none;
}
.n-column-picker summary::-webkit-details-marker {
  display: none;
}
.n-column-picker summary > svg {
  transition: transform 200ms var(--n-ease);
}
.n-column-picker[open] summary > svg {
  transform: rotate(180deg);
}
.n-pin-row button[aria-pressed="true"] svg {
  fill: currentColor;
  transform: none;
}
.n-todo-row > span > svg path {
  stroke-width: 1.5;
  transition: stroke-dashoffset 450ms ease-out;
}
